using System;
using System.Collections;
using Astrea.GameStates;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EndOfAllTurnState", menuName = "Data/Battle/Game States/EndOfAllTurn State")]
public class EndOfAllTurnState : GameState
{
	[Header("Events")]
	[SerializeField]
	private VoidEvent OnEndOfAllTurns;

	[NonSerialized]
	private bool isInitialized;

	public void OnReset()
	{
		isInitialized = false;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		if (!isInitialized)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(StartEndOfAllTurns());
			return;
		}
		ReferenceSingleton<TurnManager>.Instance.StartNextTurn();
		isInitialized = false;
	}

	private IEnumerator StartEndOfAllTurns()
	{
		Debug.Log("============================== END OF ALL TURN ==================================");
		isInitialized = true;
		OnEndOfAllTurns.Raise();
		yield return new WaitForSeconds(0.15f);
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState)
		{
			OnStartState();
		}
	}

	public override void OnEndState()
	{
	}
}
